cat > tests/CheckoutPricing.UnitTest/Discount/DiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Discount;

public sealed class DiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeCustomerIsCharged9500CentsOn10000()
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverCustomerIsCharged9000CentsOn10000()
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldCustomerIsCharged8500CentsOn10000()
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }
}
EOF
